const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alBayda = ee.Geometry.Point(21.7226, 32.7773); // Al Bayda, Libya coordinates

  const date8 = '2023-09-08';
  const date13 = '2023-09-13';

  const bandName = 'avg_rad'; // Average Radiance band for VIIRS DNB

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG')
    .select(bandName);

  // Function to get image for a specific date and calculate stats
  const getDailyIntensity = async (date, name) => {
    let images = collection.filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(alBayda);

    const size = await images.size().getInfo();
    if (size === 0) {
      console.log(`${name} Images: 0`);
      return { value: null, pixels: 0, status: 'C1' }; // No images found
    }

    const image = images.first();

    // Check for valid pixels
    const pixelCount = await image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: alBayda,
      scale: 750, // VIIRS DNB resolution
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (pixelCount === 0) {
      console.log(`${name} Images: ${size} (Val: 0.0, Pixels: 0)`);
      return { value: null, pixels: 0, status: 'C2' }; // No valid pixels after implicit masking
    }

    // Calculate mean intensity
    const intensity = await image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: alBayda,
      scale: 750,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    console.log(`${name} Images: ${size} (Val: ${intensity !== null ? intensity.toFixed(3) : 'NaN'}, Pixels: ${pixelCount})`);

    return { value: intensity, pixels: pixelCount, status: 'OK' };
  };

  const result8 = await getDailyIntensity(date8, 'Sept 8');
  if (result8.status === 'C1' || result8.status === 'C2') {
    if (result8.status === 'C1') console.log("C1: No images found for September 8, 2023.");
    if (result8.status === 'C2') console.log("C2: No valid pixels found for September 8, 2023 after processing.");
    return;
  }

  const result13 = await getDailyIntensity(date13, 'Sept 13');
  if (result13.status === 'C1' || result13.status === 'C2') {
    if (result13.status === 'C1') console.log("C1: No images found for September 13, 2023.");
    if (result13.status === 'C2') console.log("C2: No valid pixels found for September 13, 2023 after processing.");
    return;
  }

  // 3. Calculation and Validation
  const intensity8 = result8.value;
  const intensity13 = result13.value;

  if (intensity8 === null || isNaN(intensity8) || intensity13 === null || isNaN(intensity13)) {
    console.log("C3: Calculation resulted in invalid value (None/NaN).");
    return;
  }

  const decreased = intensity13 < intensity8;

  console.log(`Intensity on ${date8}: ${intensity8.toFixed(3)} nW/cm²/sr`);
  console.log(`Intensity on ${date13}: ${intensity13.toFixed(3)} nW/cm²/sr`);
  console.log(`Difference (Sept 13 - Sept 8): ${(intensity13 - intensity8).toFixed(3)} nW/cm²/sr`);

  if (decreased) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
